            [
                "chapter" => 112,
                "verses" => [
                    1 => "Aleluia!<br /> Feliz aquele que teme a Deus, o Senhor,<br /> que tem prazer em obedecer<br /> aos seus mandamentos!",
                    2 => "Os filhos desse homem serão poderosos<br /> na Terra Prometida,<br /> e os seus descendentes<br /> serão abençoados.",
                    3 => "Na sua casa há muita riqueza,<br /> e ele é sempre bem-sucedido.",
                    4 => "A luz brilha na escuridão<br /> para aqueles que são corretos,<br /> para aqueles que são bondosos,<br /> misericordiosos e honestos.",
                    5 => "Feliz aquele que tem pena dos outros<br /> e empresta generosamente<br /> e que dirige os seus negócios<br /> com honestidade!",
                    6 => "Quem é correto nunca fracassará<br /> e será lembrado para sempre.",
                    7 => "Ele não tem medo de receber<br /> más notícias;<br /> a sua fé é forte, pois ele confia<br /> no Senhor.",
                    8 => "Ele não fica preocupado, nem tem medo;<br /> ele tem certeza de que os seus inimigos<br /> serão derrotados.",
                    9 => "Ele dá generosamente aos pobres,<br /> e a sua bondade dura para sempre.<br /> Ele é poderoso e respeitado.",
                    10 => "Os maus veem isso e ficam com raiva;<br /> olham com ódio e se acabam.<br /> A esperança dos maus dá em nada.",
                ],
            ],
            [
                "chapter" => 113,
                "verses" => [
                    1 => "Aleluia!<br /> Servos de Deus, o Senhor, louvem o seu nome!",
                    2 => "Que o nome do Senhor seja louvado<br /> agora e para sempre!",
                    3 => "Desde o nascer até o pôr do sol,<br /> que o nome do Senhor seja louvado!",
                    4 => "O Senhor governa todas as nações;<br /> a sua glória está acima dos céus.",
                    5 => "Não há ninguém como o Senhor,<br /> nosso Deus,<br /> que tem o seu trono nas alturas,",
                    6 => "mas se inclina para ver o que há<br /> no céu e na terra.",
                    7 => "Ele livra da humilhação os pobres<br /> e tira da miséria os necessitados;",
