            [
                "chapter" => 114,
                "verses" => [
                    1 => "Quando os descendentes de Jacó,<br /> o povo de Israel,<br /> saíram do Egito, aquela terra estrangeira,",
                    2 => "Judá se tornou o povo escolhido de Deus,<br /> Israel ficou sendo a sua propriedade.",
                    3 => "O mar Vermelho olhou e fugiu;<br /> o rio Jordão parou de correr.",
                    4 => "As montanhas pularam como carneiros,<br /> e os montes saltaram como carneirinhos.",
                    5 => "Que aconteceu, ó mar,<br /> para que você fugisse assim?<br /> E, você, rio Jordão,<br /> por que parou de correr?",
                    6 => "Ó montanhas, por que vocês pularam<br /> como carneiros?<br /> Montes, por que vocês saltaram<br /> como carneirinhos?",
                    7 => "Trema, ó terra, na vinda do Senhor,<br /> na presença do Deus de Jacó,",
