            [
                "chapter" => 116,
                "verses" => [
                    1 => "Eu amo a Deus, o Senhor,<br /> porque ele me ouve;<br /> ele escuta as minhas orações.",
                    2 => "Ele me ouve<br /> sempre que eu clamo pedindo socorro.",
                    3 => "Os laços da morte estavam me apertando,<br /> os horrores da sepultura<br /> tomaram conta de mim,<br /> e eu fiquei aflito e apavorado.",
                    4 => "Então clamei ao Senhor, pedindo:<br /> “Ó Senhor Deus, eu te peço:<br /> Salva-me da morte!”",
                    5 => "O Senhor é bondoso e fiel;<br /> o nosso Deus tem compaixão de nós.",
                    6 => "O Senhor protege os que não podem<br /> se defender.<br /> Quando eu estava em perigo,<br /> ele me salvou.",
                    7 => "Meu ser inteiro, continue confiando<br /> em Deus, o Senhor,<br /> pois ele tem sido bom para mim!",
                    8 => "Deus me livrou da morte,<br /> fez parar as minhas lágrimas<br /> e não deixou que eu caísse<br /> na desgraça.",
                    9 => "Por isso, no mundo dos que estão vivos,<br /> viverei uma vida de obediência a ele.",
                    10 => "Eu continuei crendo,<br /> mesmo quando disse:<br /> “estou completamente esmagado.”",
                    11 => "Não parei de crer,<br /> mesmo quando afirmei, sem pensar:<br /> “não se pode confiar em ninguém.”",
                    12 => "Que posso eu oferecer a Deus, o Senhor,<br /> por tudo de bom que ele me tem dado?",
                    13 => "Levarei ao Senhor uma oferta de vinho<br /> para lhe dar graças porque me salvou.",
                    14 => "Na reunião de todo o seu povo<br /> eu lhe darei o que prometi.",
                    15 => "O Senhor Deus sente pesar<br /> quando vê morrerem os que são fiéis a ele.",
                    16 => "Ó Senhor, eu sou teu servo;<br /> eu te sirvo, como te servia<br /> a minha mãe.<br /> Tu me livraste da morte.",
                    17 => "Eu te darei uma oferta de gratidão<br /> e a ti farei as minhas orações.",
