            [
                "chapter" => 118,
                "verses" => [
                    1 => "Deem graças a Deus, o Senhor,<br /> porque ele é bom<br /> e porque o seu amor dura para sempre.",
                    2 => "Que o povo de Israel diga:<br /> “O seu amor dura para sempre!”",
                    3 => "Que os sacerdotes de Deus digam:<br /> “O seu amor dura para sempre!”",
                    4 => "E que todos os que o temem digam:<br /> “O seu amor dura para sempre!”",
                    5 => "Na minha aflição,<br /> eu clamei ao Senhor;<br /> ele me respondeu e me livrou<br /> da angústia.",
                    6 => "O Senhor está comigo,<br /> e eu não tenho medo;<br /> que mal pode alguém me fazer?",
                    7 => "O Senhor está comigo;<br /> é ele quem me ajuda.<br /> Por isso, verei a derrota<br /> dos meus inimigos.",
                    8 => "É melhor confiar no Senhor,<br /> do que depender de seres humanos.",
                    9 => "É melhor confiar no Senhor<br /> do que depender de pessoas importantes.",
                    10 => "Os inimigos que estavam em volta de mim<br /> eram muitos,<br /> mas, pelo poder de Deus, o Senhor,<br /> eu acabei com eles.",
                    11 => "Eles me cercaram por todos os lados,<br /> mas, pelo poder do Senhor,<br /> eu acabei com eles.",
                    12 => "Eles se juntaram, como abelhas,<br /> em volta de mim,<br /> porém foram queimados no fogo<br /> como galhos secos;<br /> pelo poder do Senhor,<br /> eu acabei com eles.",
                    13 => "Eles me atacaram com violência,<br /> e eu quase fui derrotado,<br /> porém o Senhor me ajudou.",
                    14 => "O Senhor Deus me torna forte<br /> e poderoso;<br /> ele me salvou.",
                    15 => "Escutem os gritos alegres de vitória<br /> no acampamento do povo de Deus:<br /> “O poder do Senhor<br /> nos deu a vitória.",
                    16 => "Com o seu poder ele fez grandes coisas.<br /> O poder do Senhor<br /> nos deu a vitória.”",
                    17 => "Não vou morrer;<br /> pelo contrário, vou viver<br /> e anunciar o que o Senhor Deus<br /> tem feito.",
                    18 => "Ele me castigou com dureza,<br /> mas não deixou que eu morresse.",
                    19 => "Abram os portões do Templo para mim;<br /> eu entrarei e louvarei o Senhor.",
                    20 => "Este é o portão do Senhor;<br /> somente os que lhe obedecem<br /> podem entrar por ele.",
                    21 => "Ó Deus, eu te louvo<br /> porque me escutaste<br /> e me deste a vitória.",
                    22 => "A pedra que os construtores rejeitaram<br /> veio a ser a mais importante de todas.",
                    23 => "Isso foi feito pelo Senhor<br /> e é uma coisa maravilhosa!",
                    24 => "Este é o dia da vitória<br /> de Deus, o Senhor;<br /> que seja para nós um dia de felicidade<br /> e alegria!",
                    25 => "Salva-nos, ó Senhor, salva-nos!<br /> Dá-nos prosperidade, ó Deus!",
                    26 => "Que Deus abençoe aquele que vem<br /> em nome de Deus, o Senhor!<br /> Daqui do Templo do Senhor,<br /> nós abençoamos todos vocês.",
                    27 => "O Senhor é Deus; ele é a nossa luz.<br /> Com ramos nas mãos, comecem a festa<br /> e andem em volta do altar.",
                    28 => "Tu és o meu Deus — eu te louvarei;<br /> tu és o meu Deus — eu anunciarei<br /> a tua grandeza.",
                    29 => "Deem graças a Deus, o Senhor,<br /> porque ele é bom<br /> e porque o seu amor dura para sempre.",
                ],
            ],
            [
                "chapter" => 119,
                "verses" => [
                    1 => "Felizes são os que não podem<br /> ser acusados de nada,<br /> que vivem de acordo com a lei<br /> de Deus, o Senhor!",
                    2 => "Felizes os que guardam<br /> os mandamentos de Deus<br /> e lhe obedecem de todo o coração!",
                    3 => "Felizes os que não praticam o mal,<br /> os que andam nos caminhos de Deus!",
                    4 => "Tu, ó Deus, nos deste as tuas leis<br /> e mandaste que as cumpríssemos<br /> fielmente.",
                    5 => "Como desejo obedecer às tuas ordens<br /> e cumpri-las com fidelidade!",
                    6 => "Se eu der atenção<br /> a todos os teus mandamentos,<br /> não passarei vergonha.",
                    7 => "Com um coração sincero eu te louvarei<br /> à medida que for aprendendo<br /> os teus justos ensinamentos.",
                    8 => "Obedecerei às tuas leis;<br /> peço-te que não me abandones nunca.",
                    9 => "Como pode um jovem conservar pura<br /> a sua vida?<br /> É só obedecer aos teus mandamentos.",
                    10 => "Eu procuro te servir de todo o coração;<br /> não deixes que eu me desvie<br /> dos teus mandamentos.",
                    11 => "Guardo a tua palavra no meu coração<br /> para não pecar contra ti.",
                    12 => "Eu te louvo, ó Senhor Deus!<br /> Ensina-me as tuas leis.",
                    13 => "Costumo repetir em voz alta<br /> todas as ordens que tens dado.",
                    14 => "Fico mais alegre em seguir<br /> os teus mandamentos<br /> do que em ser muito rico.",
                    15 => "Estudo as tuas leis<br /> e examino os teus ensinamentos.",
                    16 => "As tuas leis são o meu prazer;<br /> não esqueço a tua palavra.",
                    17 => "Senhor, trata com bondade<br /> este teu servo,<br /> para que eu possa continuar vivo<br /> e obedecer à tua palavra!",
                    18 => "Abre os meus olhos<br /> para que eu possa ver<br /> as verdades maravilhosas da tua lei.",
                    19 => "Viverei poucos anos aqui na terra;<br /> não escondas de mim<br /> os teus mandamentos.",
                    20 => "O meu coração sofre, ansioso,<br /> pois, em todos os momentos,<br /> quero conhecer a tua vontade.",
                    21 => "Tu repreendes os orgulhosos;<br /> os que se desviam dos teus mandamentos<br /> são malditos.",
                    22 => "Livra-me dos insultos<br /> e das zombarias deles,<br /> pois tenho obedecido<br /> aos teus ensinamentos.",
                    23 => "Mesmo que as autoridades se reúnam<br /> e contra mim façam planos,<br /> eu, que sou teu servo, meditarei<br /> nas tuas leis.",
                    24 => "Gosto de pensar nos teus ensinamentos;<br /> eles são os meus conselheiros.",
                    25 => "Estou derrotado e caído no chão;<br /> de acordo com a tua promessa,<br /> dá-me novas forças.",
                    26 => "Contei tudo o que tenho feito,<br /> e tu me respondeste;<br /> ensina-me os teus mandamentos.",
                    27 => "Ajuda-me a compreender as tuas leis,<br /> e eu meditarei<br /> nos teus maravilhosos ensinamentos.",
                    28 => "É tanta a minha tristeza,<br /> que estou me acabando;<br /> dá-me forças, como prometeste.",
                    29 => "Não me deixes seguir o caminho errado;<br /> com a tua bondade, ensina-me a tua lei.",
                    30 => "Eu escolhi o caminho da fidelidade<br /> e tenho dado atenção às tuas ordens.",
                    31 => "Ó Senhor Deus, tenho seguido<br /> os teus ensinamentos;<br /> não me deixes passar pela vergonha<br /> do fracasso.",
                    32 => "Eu me apresso em obedecer<br /> aos teus mandamentos<br /> porque assim tu me darás<br /> mais entendimento.",
                    33 => "Ó Senhor Deus, ensina-me a entender<br /> as tuas leis,<br /> e eu sempre as seguirei.",
                    34 => "Dá-me entendimento para que eu possa<br /> guardar a tua lei<br /> e cumpri-la de todo o coração.",
                    35 => "Guia-me pelo caminho<br /> dos teus mandamentos,<br /> pois neles encontro a felicidade.",
                    36 => "Faze com que eu queira obedecer<br /> aos teus ensinamentos,<br /> em vez de querer ajuntar riquezas.",
                    37 => "Não me deixes ficar pensando<br /> em coisas sem valor;<br /> sê bondoso para comigo, como prometeste.",
                    38 => "Eu sou teu servo; cumpre a promessa<br /> que me fizeste,<br /> a promessa que fazes aos que te temem.",
                    39 => "Livra-me dos insultos,<br /> que me causam medo;<br /> os teus julgamentos são bons.",
                    40 => "Eu quero muito obedecer às tuas leis.<br /> Conserva-me vivo, pois tu és justo.",
                    41 => "Ó Senhor Deus, mostra-me<br /> o quanto me amas<br /> e livra-me dos meus inimigos,<br /> de acordo com a tua promessa!",
                    42 => "Então saberei responder<br /> aos que me insultam,<br /> pois eu confio na tua palavra.",
                    43 => "Ajuda-me a falar sempre a verdade,<br /> pois a minha esperança<br /> está nos teus julgamentos.",
                    44 => "Todos os dias obedecerei à tua lei;<br /> eu sempre a cumprirei.",
                    45 => "Viverei à vontade, livre de perigos,<br /> porque tenho procurado seguir<br /> os teus ensinamentos.",
                    46 => "Anunciarei aos reis as tuas ordens<br /> e não ficarei envergonhado.",
                    47 => "Os teus mandamentos me trazem alegria,<br /> pois eu os amo.",
                    48 => "Respeito e amo os teus mandamentos<br /> e medito nas tuas leis.",
                    49 => "Lembra da promessa que fizeste a mim,<br /> este teu servo,<br /> a promessa que tem sido<br /> a minha esperança.",
                    50 => "No sofrimento, eu fui consolado<br /> porque a tua promessa me deu vida.",
                    51 => "Os orgulhosos estão sempre<br /> zombando de mim,<br /> mas eu não tenho me afastado da tua lei.",
                    52 => "Eu lembro dos teus julgamentos<br /> do passado,<br /> e eles me confortam, ó Senhor.",
                    53 => "Fico muito revoltado<br /> quando vejo os maus quebrando a tua lei.",
                    54 => "Na minha curta vida aqui na terra,<br /> faço canções<br /> sobre os teus mandamentos.",
                    55 => "De noite, eu penso em ti,<br /> ó Senhor Deus,<br /> e medito na tua lei.",
                    56 => "O meu dever nesta vida é este:<br /> obedecer aos teus mandamentos.",
                    57 => "Tu, ó Senhor Deus, és tudo<br /> o que eu tenho;<br /> prometo obedecer às tuas leis.",
                    58 => "De todo o coração, eu te peço:<br /> tem misericórdia de mim,<br /> como prometeste.",
                    59 => "Tenho pensado na minha maneira de agir<br /> e prometo seguir os teus ensinamentos.",
                    60 => "Com toda a pressa e sem demora,<br /> procuro obedecer aos teus mandamentos.",
                    61 => "Os maus armaram uma armadilha<br /> para me pegar,<br /> mas eu não esqueço a tua lei.",
                    62 => "Por causa dos teus ensinamentos justos,<br /> eu me levanto no meio da noite<br /> para te louvar.",
                    63 => "Eu sou amigo de todos os que te temem,<br /> de todos os que obedecem às tuas leis.",
                    64 => "Ó Senhor Deus, a terra está cheia<br /> do teu amor;<br /> ensina-me os teus mandamentos.",
                    65 => "Ó Senhor Deus, tu cumpriste<br /> a tua promessa<br /> e tens sido bom para mim,<br /> este teu servo.",
                    66 => "Dá-me sabedoria e conhecimento,<br /> pois confio nos teus mandamentos.",
                    67 => "Antes de me castigares,<br /> eu andava errado,<br /> mas agora obedeço à tua palavra.",
                    68 => "Ó Deus, tu és bom e fazes o bem;<br /> ensina-me os teus mandamentos.",
                    69 => "Os orgulhosos dizem mentiras<br /> contra mim,<br /> mas eu, de todo o coração,<br /> obedeço aos teus mandamentos.",
                    70 => "Esses homens não querem aprender<br /> a tua lei,<br /> porém eu tenho prazer nela.",
                    71 => "Foi bom que eu tivesse sido castigado,<br /> pois assim aprendi os teus mandamentos.",
                    72 => "A tua lei vale muito mais para mim<br /> do que toda a riqueza do mundo.",
                    73 => "Ó Deus, as tuas mãos me criaram<br /> e me formaram;<br /> dá-me entendimento para que eu possa<br /> aprender as tuas leis.",
                    74 => "Aqueles que te temem se alegram<br /> quando me veem<br /> porque a minha esperança<br /> está na tua palavra.",
                    75 => "Ó Senhor Deus, eu sei<br /> que os teus julgamentos são justos<br /> e que me castigas porque és fiel.",
                    76 => "Peço que o teu amor me console,<br /> como prometeste a mim,<br /> este teu servo!",
                    77 => "Tem compaixão de mim,<br /> e eu continuarei vivo,<br /> pois gosto de pensar na tua lei.",
                    78 => "Que os orgulhosos fiquem envergonhados,<br /> pois me acusam com mentiras!<br /> Mas eu meditarei nos teus ensinamentos.",
                    79 => "Que venham para o meu lado<br /> os que te temem,<br /> os que conhecem os teus mandamentos!",
                    80 => "Que eu obedeça completamente<br /> aos teus mandamentos<br /> e não sofra a vergonha do fracasso!",
                    81 => "Ó Deus, estou aflito, esperando<br /> que tu me livres dos meus inimigos;<br /> eu ponho a minha esperança<br /> na tua palavra.",
                    82 => "Os meus olhos estão cansados<br /> de tanto olhar,<br /> esperando o que prometeste,<br /> e eu pergunto:<br /> “Quando vens me consolar?”",
                    83 => "Sou tão inútil como um odre<br /> cheio de furos,<br /> porém não esqueço<br /> os teus mandamentos.",
                    84 => "Até quando vai este teu servo<br /> ter de esperar?<br /> Quando vais castigar<br /> os que me perseguem?",
                    85 => "Os orgulhosos, que não obedecem<br /> à tua lei,<br /> cavaram covas para me pegar.",
                    86 => "Todos os teus mandamentos<br /> merecem confiança.<br /> Ajuda-me, pois sou perseguido<br /> por mentirosos.",
                    87 => "Eles quase conseguiram me matar,<br /> porém eu não abandono<br /> os teus ensinamentos.",
                    88 => "Por causa do teu amor,<br /> livra-me da morte<br /> para que eu possa obedecer<br /> aos teus mandamentos.",
                    89 => "Ó Senhor Deus, a tua palavra<br /> dura para sempre;<br /> ela é firme como o céu.",
                    90 => "A tua fidelidade permanece<br /> em todas as gerações;<br /> tu colocaste a terra no seu lugar,<br /> e ela fica firme.",
                    91 => "De acordo com as tuas ordens<br /> todas as coisas permanecem até hoje,<br /> pois tudo te obedece.",
                    92 => "Se a tua lei não tivesse sido<br /> o motivo da minha alegria,<br /> eu já teria morrido de tanto sofrer.",
                    93 => "Nunca esquecerei<br /> os teus ensinamentos,<br /> pois é por meio deles<br /> que tens conservado a minha vida.",
                    94 => "Livra-me dos meus inimigos,<br /> pois sou teu<br /> e tenho procurado obedecer<br /> aos teus mandamentos.",
                    95 => "Os maus estão esperando<br /> a hora de me matarem,<br /> mas eu meditarei nas tuas leis.",
                    96 => "Tenho visto que todas as coisas<br /> têm o seu limite,<br /> mas o teu mandamento se aplica a tudo.",
                    97 => "Como eu amo a tua lei!<br /> Penso nela o dia todo.",
                    98 => "O teu mandamento está sempre comigo<br /> e faz com que eu seja mais sábio<br /> do que os meus inimigos.",
                    99 => "Eu entendo mais do que todos<br /> os meus professores<br /> porque medito nos teus ensinamentos.",
                    100 => "Tenho mais sabedoria do que os velhos<br /> porque obedeço aos teus mandamentos.",
                    101 => "Não tenho andado pelos caminhos<br /> da maldade,<br /> pois quero obedecer à tua palavra.",
                    102 => "Não tenho deixado de cumprir<br /> as tuas ordens<br /> porque és tu que me ensinas.",
                    103 => "Como são doces as tuas palavras!<br /> São mais doces do que o mel.",
                    104 => "Por meio das tuas leis,<br /> consigo a sabedoria<br /> e assim detesto todos os caminhos<br /> da mentira.",
                    105 => "A tua palavra é lâmpada para guiar<br /> os meus passos,<br /> é luz que ilumina o meu caminho.",
                    106 => "Cumprirei o juramento que fiz<br /> de seguir os teus justos ensinamentos.",
                    107 => "Ó Senhor Deus, os meus sofrimentos<br /> são terríveis;<br /> conserva-me vivo, como prometeste.",
                    108 => "Ó Senhor, aceita a minha oração<br /> de agradecimento<br /> e ensina-me os teus mandamentos!",
                    109 => "A minha vida está sempre em perigo;<br /> no entanto não esqueço a tua lei.",
                    110 => "Os maus armaram uma armadilha<br /> para me pegar,<br /> mas eu não desobedeci<br /> aos teus mandamentos.",
                    111 => "Os teus ensinamentos<br /> são a minha riqueza para sempre;<br /> eles são a alegria do meu coração.",
                    112 => "Eu resolvi obedecer às tuas ordens<br /> até o fim da minha vida.",
                    113 => "Não suporto as pessoas falsas,<br /> mas amo a tua lei.",
                    114 => "Tu és o meu esconderijo<br /> e o meu escudo;<br /> eu ponho a minha esperança<br /> na tua promessa.",
                    115 => "Afastem-se de mim,<br /> vocês que praticam o mal,<br /> e eu obedecerei aos mandamentos<br /> do meu Deus!",
                    116 => "Dá-me forças, como prometeste,<br /> e eu continuarei vivo;<br /> não permitas que eu fique desiludido<br /> com a minha esperança.",
                    117 => "Dá-me apoio, e estarei em segurança;<br /> e sempre darei atenção às tuas ordens.",
                    118 => "Tu rejeitas todos os que desobedecem<br /> às tuas leis,<br /> pois os seus planos enganosos<br /> não valem nada.",
                    119 => "Tu tratas todos os maus como lixo,<br /> e por isso eu amo os teus ensinamentos.",
                    120 => "Eu tremo diante de ti<br /> e tenho medo dos teus julgamentos.",
                    121 => "Tenho feito o que é certo e bom;<br /> não me entregues nas mãos<br /> dos meus inimigos.",
                    122 => "Promete que ajudarás a mim,<br /> este teu servo.<br /> Não deixes que os orgulhosos<br /> me façam sofrer.",
                    123 => "Os meus olhos estão cansados<br /> de tanto olhar,<br /> esperando que me salves<br /> e assim cumpras a tua promessa.",
                    124 => "Trata este teu servo<br /> de acordo com o teu amor<br /> e ensina-me os teus mandamentos.",
                    125 => "Sou teu servo; por isso,<br /> dá-me sabedoria<br /> para que eu possa conhecer<br /> os teus ensinamentos.",
                    126 => "Ó Senhor Deus, já é tempo de agires,<br /> pois a tua lei está sendo desobedecida.",
                    127 => "Eu amo os teus mandamentos<br /> mais do que o ouro,<br /> mais do que o ouro puro.",
                    128 => "Por isso, sigo os teus ensinamentos<br /> e detesto todos os caminhos da mentira.",
                    129 => "Os teus mandamentos são maravilhosos,<br /> e por isso os cumpro de todo o coração.",
                    130 => "A explicação da tua palavra traz luz<br /> e dá sabedoria às pessoas simples.",
                    131 => "Abro a boca e suspiro,<br /> pois o que mais desejo na vida<br /> é obedecer aos teus mandamentos.",
                    132 => "Olha de novo para mim e tem compaixão,<br /> como sempre fazes com os que te amam.",
                    133 => "Conserva-me firme, como prometeste;<br /> não deixes que eu seja dominado<br /> pelo mal.",
                    134 => "Livra-me daqueles que me maltratam<br /> para que eu possa obedecer<br /> aos teus mandamentos.",
                    135 => "Olha com bondade para mim, teu servo,<br /> e ensina-me as tuas leis.",
                    136 => "As minhas lágrimas correm como um rio<br /> porque os outros não obedecem<br /> à tua lei.",
                    137 => "Tu és justo, ó Senhor Deus;<br /> as tuas leis são certas.",
                    138 => "Os ensinamentos que tens dado<br /> são completamente certos e justos.",
                    139 => "Fico queimando de raiva<br /> porque os meus inimigos desprezam<br /> a tua palavra.",
                    140 => "Como é firme a tua promessa!<br /> E como este teu servo a ama!",
                    141 => "Sou humilde e desprezado,<br /> porém não esqueço<br /> os teus ensinamentos.",
                    142 => "A tua justiça dura para sempre,<br /> e a tua lei é sempre verdadeira.",
                    143 => "Os sofrimentos e a ansiedade<br /> me atingem,<br /> mas os teus mandamentos me alegram.",
                    144 => "Os teus ensinamentos<br /> são sempre certos;<br /> dá-me entendimento,<br /> e continuarei vivo.",
                    145 => "De todo o coração, eu clamo a ti;<br /> responde-me, ó Senhor,<br /> e obedecerei aos teus mandamentos!",
                    146 => "Eu clamo pedindo socorro;<br /> livra-me dos meus inimigos<br /> e eu seguirei as tuas ordens.",
                    147 => "Antes do nascer do sol, eu clamo<br /> pedindo ajuda,<br /> pois a minha esperança está<br /> na tua promessa.",
                    148 => "Eu fico acordado a noite inteira<br /> para meditar na tua palavra.",
                    149 => "Ouve-me, ó Senhor Deus,<br /> por causa do teu amor!<br /> Conserva-me vivo,<br /> de acordo com a tua justa vontade.",
                    150 => "Os meus terríveis perseguidores<br /> estão chegando perto;<br /> é gente que nunca obedece à tua lei.",
                    151 => "Mas tu, ó Senhor, estás perto de mim,<br /> e todos os teus mandamentos<br /> são verdadeiros.",
                    152 => "Faz muito tempo que conheço<br /> os teus ensinamentos;<br /> tu os deste a fim de durarem<br /> para sempre.",
                    153 => "Ó Deus, olha para o meu sofrimento<br /> e socorre-me,<br /> pois não tenho desprezado a tua lei!",
                    154 => "Defende a minha causa e livra-me<br /> dos meus inimigos;<br /> conserva-me vivo, como prometeste.",
                    155 => "Os maus não serão salvos<br /> dos seus sofrimentos<br /> porque eles não se importam<br /> com as tuas leis.",
                    156 => "Como é grande a tua compaixão,<br /> ó Senhor!<br /> Conserva-me vivo,<br /> de acordo com a tua justa vontade.",
                    157 => "Tenho muitos inimigos e perseguidores,<br /> porém não deixo de obedecer<br /> aos teus mandamentos.",
                    158 => "Quando olho para aqueles traidores,<br /> sinto nojo<br /> porque eles não obedecem à tua lei.",
                    159 => "Vê como amo os teus ensinamentos,<br /> ó Senhor!<br /> Conserva-me vivo,<br /> por causa do teu amor.",
                    160 => "Todas as tuas palavras são verdadeiras;<br /> os teus mandamentos são justos<br /> e duram para sempre.",
                    161 => "Os poderosos me atacam injustamente,<br /> mas eu respeito os teus mandamentos.",
                    162 => "Como sou feliz<br /> por causa das tuas promessas,<br /> tão feliz como alguém que encontra<br /> um grande tesouro!",
                    163 => "Odeio e detesto a mentira,<br /> mas amo a tua lei.",
                    164 => "Sete vezes por dia, eu te louvo<br /> por causa dos teus julgamentos justos.",
                    165 => "Aqueles que amam a tua lei<br /> têm muita segurança,<br /> e não há nada que os faça cair.",
                    166 => "Espero que me livres dos meus inimigos,<br /> ó Senhor Deus,<br /> pois cumpro os teus mandamentos.",
                    167 => "Obedeço aos teus ensinamentos;<br /> eu os amo com todo o coração.",
                    168 => "Cumpro os teus mandamentos<br /> e as tuas ordens,<br /> pois tu vês tudo o que eu faço.",
                    169 => "Que o meu grito de socorro chegue a ti,<br /> ó Senhor Deus!<br /> Dá-me sabedoria como prometeste.",
                    170 => "Que a minha oração<br /> chegue diante de ti!<br /> Conforme a tua promessa,<br /> livra-me dos meus inimigos!",
                    171 => "Sempre te louvarei,<br /> pois me ensinas as tuas leis.",
                    172 => "Cantarei a respeito da tua lei,<br /> pois os teus mandamentos são justos.",
                    173 => "Ó Deus, que a tua mão esteja<br /> sempre pronta para me ajudar,<br /> pois sigo os teus mandamentos!",
                    174 => "Como desejo que me ajudes,<br /> ó Senhor Deus!<br /> Na tua lei, encontro a felicidade.",
                    175 => "Conserva-me vivo<br /> para que eu possa te louvar.<br /> Que os teus ensinamentos<br /> sirvam de ajuda para mim!",
                    176 => "Como ovelha perdida,<br /> tenho andado sem rumo.<br /> Ó Senhor Deus, vem buscar<br /> este teu servo,<br /> pois não esqueço<br /> os teus mandamentos!",
                ],
            ],
            [
                "chapter" => 120,
                "verses" => [
                    1 => "Quando estive aflito,<br /> pedi ajuda a Deus, o Senhor,<br /> e ele me respondeu.",
                    2 => "Ó Senhor, livra-me<br /> dos mentirosos e dos falsos!",
                    3 => "Mentirosos, que será que Deus<br /> vai fazer com vocês?<br /> Como será que ele vai castigá-los?",
                    4 => "Ele os castigará com as flechas afiadas<br /> de um soldado e com brasas.",
                    5 => "Viver entre vocês me faz sofrer tanto<br /> como se eu morasse em Meseque<br /> ou entre a gente de Quedar .",
                    6 => "Há muito tempo que estou morando<br /> com aqueles que odeiam a paz.",
                    7 => "Quando falo de paz,<br /> eles falam a favor de guerra.",
                ],
            ],
            [
                "chapter" => 121,
                "verses" => [
                    1 => "Olho para os montes e pergunto:<br /> “De onde virá o meu socorro?”",
                    2 => "O meu socorro vem do Senhor Deus,<br /> que fez o céu e a terra.",
                    3 => "Ele, o seu protetor,<br /> está sempre alerta<br /> e não deixará que você caia.",
                    4 => "O protetor do povo de Israel<br /> nunca dorme, nem cochila.",
                    5 => "O Senhor guardará você;<br /> ele está sempre ao seu lado<br /> para protegê-lo.",
                    6 => "O sol não lhe fará mal de dia,<br /> nem a lua, de noite.",
                    7 => "O Senhor guardará você<br /> de todo perigo;<br /> ele protegerá a sua vida.",
                    8 => "Ele o guardará quando você for<br /> e quando voltar,<br /> agora e sempre.",
                ],
