            [
                "chapter" => 122,
                "verses" => [
                    1 => "Fiquei alegre quando me disseram:<br /> “Vamos à casa de Deus, o Senhor.”",
                    2 => "E agora aqui estamos,<br /> dentro de Jerusalém.",
                    3 => "Jerusalém é uma cidade construída<br /> de novo,<br /> onde o povo se reúne.",
                    4 => "Para cá sobem as tribos,<br /> as tribos de Israel,<br /> para dar graças ao Senhor,<br /> como ele ordenou.",
                    5 => "Aqui estão os tribunais de justiça,<br /> onde o rei julga o seu povo.",
                    6 => "Orem para que haja paz em Jerusalém.<br /> “Ó Jerusalém, que prosperem<br /> aqueles que a amam!",
                    7 => "Que haja paz na cidade protegida<br /> por muralhas!<br /> Que haja segurança nos seus palácios!”",
                    8 => "Eu amo os meus patrícios e amigos<br /> e por isso digo a Jerusalém:<br /> “Que a paz esteja com você!”",
                    9 => "Eu amo o Templo do Senhor,<br /> o nosso Deus,<br /> e por isso oro pela prosperidade<br /> de Jerusalém.",
