            [
                "chapter" => 126,
                "verses" => [
                    1 => "Quando o Senhor Deus<br /> nos trouxe de volta para Jerusalém,<br /> parecia que estávamos sonhando.",
                    2 => "Como rimos e cantamos de alegria!<br /> Então as outras nações disseram:<br /> “O Senhor fez grandes coisas<br /> por eles!”",
                    3 => "De fato, o Senhor fez grandes coisas<br /> por nós,<br /> e por isso estamos alegres.",
                    4 => "Ó Senhor, faze com que prosperemos<br /> de novo,<br /> assim como a chuva enche de novo<br /> o leito seco dos rios.",
                    5 => "Que aqueles que semeiam chorando<br /> façam a colheita com alegria!",
                    6 => "Aqueles que saíram chorando,<br /> levando a semente para semear,<br /> voltarão cantando, cheios de alegria,<br /> trazendo nos braços os feixes<br /> da colheita.",
                ],
            ],
            [
                "chapter" => 127,
                "verses" => [
                    1 => "Se o Senhor Deus não edificar a casa,<br /> não adianta nada trabalhar<br /> para construí-la.<br /> Se o Senhor não proteger a cidade,<br /> não adianta nada os guardas<br /> ficarem vigiando.",
                    2 => "Não adianta trabalhar demais<br /> para ganhar o pão,<br /> levantando cedo e deitando tarde,<br /> pois é Deus quem dá o sustento<br /> aos que ele ama,<br /> mesmo quando estão dormindo.",
                    3 => "Os filhos são um presente do Senhor;<br /> eles são uma verdadeira bênção.",
                    4 => "Os filhos que o homem tem<br /> na sua mocidade<br /> são como flechas<br /> nas mãos de um soldado.",
                    5 => "Feliz o homem que tem<br /> muitas dessas flechas!<br /> Ele não será derrotado<br /> quando enfrentar os seus inimigos<br /> no tribunal.",
                ],
            ],
            [
                "chapter" => 128,
                "verses" => [
                    1 => "Feliz aquele que teme a Deus, o Senhor,<br /> e vive de acordo com a sua vontade!",
                    2 => "Se você for assim,<br /> ganhará o suficiente para viver,<br /> será feliz, e tudo dará certo para você.",
                    3 => "Em casa, a sua mulher será<br /> como uma parreira<br /> que dá muita uva;<br /> e, em volta da mesa, os seus filhos<br /> serão como oliveiras novas.",
                    4 => "Quem teme ao Senhor<br /> certamente será abençoado assim.",
                    5 => "Que, do monte Sião,<br /> o Senhor o abençoe!<br /> Que, em todos os dias da sua vida,<br /> você veja o progresso de Jerusalém!",
                    6 => "E que você viva para ver<br /> os seus netos!<br /> Que a paz esteja com o povo de Israel!",
