            [
                "chapter" => 130,
                "verses" => [
                    1 => "Ó Senhor Deus, eu te chamei<br /> quando estava em profundo desespero.",
                    2 => "Escuta o meu grito, ó Senhor!<br /> Ouve o meu pedido de socorro.",
                    3 => "Se tu tivesses feito uma lista<br /> dos nossos pecados,<br /> quem escaparia da condenação?",
                    4 => "Mas tu nos perdoas,<br /> e por isso nós te tememos.",
                    5 => "Eu aguardo ansioso a ajuda<br /> de Deus, o Senhor,<br /> e confio na sua palavra.",
                    6 => "Eu espero pelo Senhor<br /> mais do que os vigias esperam<br /> o amanhecer,<br /> mais do que os vigias esperam<br /> o nascer do sol.",
                    7 => "Povo de Israel, ponha a sua esperança<br /> em Deus, o Senhor,<br /> porque o seu amor é fiel,<br /> e ele sempre está disposto a salvar.",
                    8 => "Ele salvará Israel, o seu povo,<br /> de todos os seus pecados.",
