            [
                "chapter" => 131,
                "verses" => [
                    1 => "Ó Senhor Deus, eu já não sou<br /> orgulhoso;<br /> deixei de olhar os outros com arrogância.<br /> Não vou atrás das coisas grandes<br /> e extraordinárias,<br /> que estão fora do meu alcance.",
                    2 => "Assim, como a criança desmamada<br /> fica quieta nos braços da mãe,<br /> assim eu estou satisfeito e tranquilo,<br /> e o meu coração está calmo<br /> dentro de mim.",
                    3 => "Povo de Israel, ponha a sua esperança<br /> em Deus, o Senhor,<br /> agora e sempre!",
                ],
            ],
            [
                "chapter" => 132,
                "verses" => [
                    1 => "Ó Senhor Deus, lembra de Davi<br /> e de todos os seus sofrimentos.",
                    2 => "Lembra da promessa feita por Davi,<br /> lembra deste juramento<br /> que ele fez a ti,<br /> o Senhor, o Poderoso de Jacó:",
                    3 => "“Eu não vou para casa,<br /> nem vou descansar;",
                    4 => "não vou me deitar, nem dormir",
                    5 => "enquanto não encontrar um lugar<br /> para o Senhor,<br /> uma casa para o Poderoso de Jacó.”",
                    6 => "Em Belém ouvimos falar<br /> a respeito da arca da aliança<br /> e nós a encontramos<br /> nos campos de Jearim.",
                    7 => "Então dissemos:<br /> “Vamos à casa de Deus, o Senhor;<br /> vamos adorá-lo diante do seu trono.”",
                    8 => "Ó Senhor, vem para o teu Templo,<br /> com a arca da aliança,<br /> que representa o teu poder,<br /> e fica ali para sempre!",
                    9 => "Que os teus sacerdotes façam sempre<br /> o que é certo!<br /> Que os teus servos fiéis<br /> gritem de alegria!",
                    10 => "Ó Senhor Deus, fizeste uma promessa<br /> ao teu servo Davi;<br /> portanto, não rejeites o rei<br /> que escolheste.",
                    11 => "Tu não voltarás atrás<br /> neste juramento que fizeste a Davi:<br /> “Farei com que um dos seus filhos<br /> seja rei,<br /> e ele reinará depois de você.",
                    12 => "Se os filhos de você forem fiéis<br /> à minha aliança<br /> e aos mandamentos que lhes dei,<br /> também os filhos deles<br /> sempre serão reis.”",
                    13 => "O Senhor Deus escolheu o monte Sião;<br /> ele quis que a sua casa fosse ali e disse:",
                    14 => "“Aqui viverei para sempre;<br /> é aqui que eu quero reinar.",
                    15 => "Darei de tudo com fartura a Jerusalém,<br /> darei muito alimento aos seus pobres.",
