            [
                "chapter" => 137,
                "verses" => [
                    1 => "Sentados na beira dos rios<br /> da Babilônia,<br /> chorávamos quando lembrávamos<br /> de Jerusalém.",
                    2 => "Penduramos as nossas liras<br /> nas árvores que havia ali.",
                    3 => "Aqueles que nos levaram<br /> como prisioneiros<br /> mandavam que cantássemos.<br /> Eles diziam:<br /> “Cantem para nós as canções de Sião.”",
                    4 => "Mas, em terra estrangeira,<br /> como podemos cantar um hino<br /> a Deus, o Senhor?",
