            [
                "chapter" => 141,
                "verses" => [
                    1 => "Ó Senhor Deus, eu clamo a ti;<br /> vem depressa me socorrer!<br /> Escuta-me quando peço a tua ajuda.",
                    2 => "Recebe a minha oração<br /> como se fosse incenso,<br /> e que as minhas mãos levantadas<br /> sejam como a oferta da tarde!",
