            [
                "chapter" => 144,
                "verses" => [
                    1 => "Louvem o Senhor Deus, a minha rocha;<br /> ele me prepara para a batalha<br /> e me ensina a combater.",
                    2 => "Ele é a minha rocha<br /> e a minha fortaleza,<br /> o meu abrigo e o meu libertador.<br /> Ele me defende como um escudo,<br /> e eu confio na sua proteção.<br /> Ele põe as nações<br /> debaixo do meu poder.",
                    3 => "Ó Senhor, que é o ser humano,<br /> para que penses nele?<br /> Que é um simples mortal,<br /> para que te preocupes com ele?",
                    4 => "O ser humano é como um sopro;<br /> a sua vida é como a sombra que passa.",
                    5 => "Ó Senhor, abre o céu e desce!<br /> Toca nas montanhas,<br /> e elas soltarão fumaça.",
                    6 => "Manda relâmpagos<br /> e espalha os inimigos;<br /> atira as tuas flechas<br /> para fazê-los fugir.",
                    7 => "Lá do alto estende a mão,<br /> tira-me do mar profundo e salva-me.<br /> Livra-me do poder dos pagãos,",
                    8 => "pois eles nunca dizem a verdade<br /> e mentem, fazendo juramentos falsos.",
                    9 => "A ti, ó Deus, eu cantarei<br /> uma nova canção;<br /> tocarei harpa de dez cordas<br /> e te cantarei louvores.",
                    10 => "Tu dás a vitória aos reis<br /> e livras da morte o teu servo Davi.",
                    11 => "Salva-me dos meus inimigos cruéis;<br /> livra-me do poder dos pagãos,<br /> pois eles nunca dizem a verdade<br /> e mentem, fazendo juramentos falsos.",
                    12 => "Que, na sua mocidade, os nossos filhos<br /> sejam como plantas viçosas,<br /> e que as nossas filhas<br /> sejam como colunas<br /> que enfeitam a frente de um palácio!",
                    13 => "Que os nossos depósitos fiquem cheios<br /> de todo tipo de mantimentos!<br /> Que, nos nossos campos, os rebanhos<br /> deem dezenas de milhares de crias!",
                    14 => "Que o gado se reproduza bem,<br /> e as vacas não percam as suas crias!<br /> E que não haja gritos de aflição<br /> nas nossas ruas!",
                    15 => "Feliz a nação que tem tudo isso!<br /> Feliz o povo cujo Deus é o Senhor!",
                ],
