            [
                "chapter" => 145,
                "verses" => [
                    1 => "Meu Deus e meu Rei,<br /> eu anunciarei a tua grandeza<br /> e sempre serei grato a ti.",
                    2 => "Todos os dias te darei graças<br /> e sempre te louvarei.",
                    3 => "O Senhor Deus é grande<br /> e merece receber altos louvores.<br /> Quem pode compreender a sua grandeza?",
                    4 => "Ó Deus, cada geração<br /> anunciará à seguinte<br /> as coisas que tens feito,<br /> e todos louvarão os teus atos poderosos.",
                    5 => "Eles falarão da tua glória<br /> e da tua majestade,<br /> e eu meditarei nas coisas maravilhosas<br /> que fazes.",
                    6 => "Falarão dos teus atos poderosos,<br /> e eu anunciarei a tua grandeza.",
                    7 => "Falarão da tua imensa bondade<br /> e cantarão com alegria<br /> a respeito da tua fidelidade.",
                    8 => "O Senhor Deus é bom<br /> e cheio de compaixão;<br /> ele demora a ficar irado<br /> e tem sempre muito amor.",
                    9 => "O Senhor é bondoso com todos<br /> e cuida com carinho<br /> de todas as suas criaturas.",
                    10 => "Ó Senhor Deus, todas as tuas criaturas<br /> te louvarão,<br /> e te darão graças<br /> os que são fiéis a ti.",
                    11 => "Todos falarão da glória<br /> do teu Reino<br /> e contarão a respeito do teu poder,",
                    12 => "para que todos os povos conheçam<br /> os teus atos poderosos<br /> e a grandeza e a glória do teu Reino.",
                    13 => "O teu Reino é eterno,<br /> e tu és Rei para sempre.<br /> O Senhor Deus sempre cumpre<br /> o que promete;<br /> ele é fiel em tudo o que faz.",
                    14 => "Ele ajuda os que estão em dificuldade<br /> e levanta os que caem.",
                    15 => "Todos os seres vivos olham para ele<br /> com esperança,<br /> e ele dá alimento a todos<br /> no tempo certo.",
                    16 => "Quando os alimenta, o Senhor Deus<br /> é generoso;<br /> ele satisfaz a todos os seres vivos.",
                    17 => "O Senhor é justo em todos os seus atos<br /> e fiel em tudo o que faz.",
                    18 => "Ele está perto de todos os que pedem<br /> a sua ajuda,<br /> dos que pedem com sinceridade.",
                    19 => "A todos os que o temem<br /> dá o que é necessário;<br /> ele ouve os seus gritos<br /> e os salva da morte.",
                    20 => "O Senhor protege os que o amam,<br /> mas destruirá todos os maus.",
                    21 => "Eu sempre louvarei o Senhor.<br /> Que todos os seres vivos<br /> louvem o Santo Deus para sempre!",
                ],
