            [
                "chapter" => 146,
                "verses" => [
                    1 => "Aleluia!<br /> Que todo o meu ser te louve, ó Senhor!",
                    2 => "A vida inteira eu louvarei o meu Deus,<br /> cantarei louvores a ele<br /> enquanto eu viver.",
                    3 => "Não ponham a sua confiança<br /> em pessoas importantes,<br /> nem confiem em seres humanos,<br /> pois eles são mortais<br /> e não podem ajudar ninguém.",
                    4 => "Quando eles morrem,<br /> voltam para o pó da terra,<br /> e naquele dia todos os seus planos<br /> se acabam.",
                    5 => "Feliz aquele que recebe ajuda<br /> do Deus de Jacó,<br /> aquele que põe a sua esperança<br /> no Senhor, seu Deus,",
                    6 => "o Criador do céu, da terra e do mar<br /> e de tudo o que neles existe!<br /> O Senhor sempre cumpre<br /> as suas promessas;",
                    7 => "ele julga a favor dos que são explorados<br /> e dá comida aos que têm fome.<br /> O Senhor Deus põe em liberdade<br /> os que estão presos",
                    8 => "e faz com que os cegos vejam.<br /> O Senhor levanta os que caem<br /> e ama aqueles que lhe obedecem.",
                    9 => "O Senhor protege os estrangeiros<br /> que moram em nossa terra;<br /> ele ajuda as viúvas e os órfãos,<br /> mas faz com que fracassem<br /> os planos dos maus.",
                    10 => "O Senhor será Rei para sempre.<br /> Ó Jerusalém, o seu Deus reinará<br /> eternamente.<br /> Aleluia!",
                ],
            ],
            [
                "chapter" => 147,
                "verses" => [
                    1 => "Aleluia!<br /> É bom cantar louvores ao nosso Deus;<br /> é agradável e certo louvá-lo.",
                    2 => "O Senhor Deus está construindo<br /> de novo Jerusalém;<br /> ele está trazendo de volta o seu povo,<br /> que foi levado como prisioneiro<br /> para outro país.",
                    3 => "Ele cura os que têm o coração partido<br /> e trata dos seus ferimentos.",
                    4 => "Foi ele quem resolveu quantas estrelas<br /> deviam existir<br /> e chama cada uma pelo nome.",
                    5 => "Deus, o Senhor nosso,<br /> é grande e poderoso;<br /> a sua sabedoria não pode ser medida.",
                    6 => "O Senhor Deus levanta os humildes,<br /> mas esmaga os maus no chão.",
                    7 => "Cantem hinos de louvor ao Senhor;<br /> toquem músicas na lira<br /> em louvor ao nosso Deus.",
                    8 => "Ele cobre de nuvens o céu,<br /> manda cair chuva na terra<br /> e faz crescer grama nas montanhas.",
                    9 => "Ele dá de comer aos animais<br /> e alimenta os filhotes dos corvos<br /> quando eles pedem.",
                    10 => "O que agrada a Deus<br /> não são cavalos fortes<br /> nem soldados corajosos,",
                    11 => "mas, sim, as pessoas que o temem<br /> e põem a sua esperança no seu amor.",
                    12 => "Louve o Senhor, ó Jerusalém!<br /> Louve o seu Deus, ó Sião!",
                    13 => "Pois ele reforça os portões da cidade<br /> e abençoa o seu povo que mora ali.",
                    14 => "Ele conserva a paz nas fronteiras<br /> e alimenta o povo com o melhor trigo.",
                    15 => "O Senhor dá uma ordem,<br /> e ela chega depressa aonde ele quer.",
                    16 => "Ele faz cair neve tão grossa como lã<br /> e espalha a geada como pó.",
                    17 => "Ele envia chuva de pedra,<br /> gelo em pedaços;<br /> ninguém suporta o frio que ele manda.",
                    18 => "Então ele dá uma ordem,<br /> e o gelo se derrete;<br /> manda o vento soprar,<br /> e as águas correm.",
                    19 => "O Senhor anuncia a sua mensagem<br /> aos descendentes de Jacó<br /> e dá as suas ordens e leis<br /> ao povo de Israel.",
                    20 => "Ele não fez assim<br /> com nenhuma outra nação;<br /> as outras nações não conhecem<br /> as suas leis.<br /> Aleluia!",
                ],
            ],
            [
                "chapter" => 148,
                "verses" => [
                    1 => "Aleluia!<br /> Todos os que estão nos céus,<br /> louvem o Senhor Deus nas alturas!",
                    2 => "Louvem o Senhor, todos os seus anjos,<br /> todos os seus exércitos celestiais!",
                    3 => "Sol e lua, louvem o Senhor!<br /> Todas as estrelas brilhantes,<br /> louvem a Deus!",
                    4 => "Que os mais altos céus o louvem<br /> e também as águas<br /> que estão acima do céu !",
                    5 => "Que todos eles louvem o Senhor,<br /> pois ele deu uma ordem,<br /> e eles foram criados!",
                    6 => "Ele mandou, e foram firmados<br /> para sempre nos seus lugares;<br /> eles não podem desobedecer.",
                    7 => "Louve o Senhor, tudo o que existe<br /> na terra:<br /> monstros do mar<br /> e todas as profundezas do oceano!",
                    8 => "Louvem o Senhor, relâmpagos<br /> e chuva de pedra, neve e nuvens,<br /> e ventos fortes, que obedecem<br /> à sua ordem!",
                    9 => "Louvem o Senhor, colinas e montanhas,<br /> florestas e árvores que dão frutas!",
                    10 => "Louvem o Senhor, todos os animais,<br /> mansos e selvagens!<br /> Louvem o Senhor, passarinhos<br /> e animais que se arrastam pelo chão!",
                    11 => "Louvem o Senhor,<br /> reis e todos os povos,<br /> governantes e todas as outras autoridades!",
                    12 => "Louvem o Senhor, moços e moças,<br /> velhos e crianças!",
                    13 => "Que todos louvem a Deus, o Senhor,<br /> porque ele é superior<br /> a todos os outros deuses!<br /> A sua glória está acima da terra e do céu.",
                    14 => "Ele fez com que a sua nação ficasse<br /> cada vez mais forte,<br /> e por isso o louvam<br /> todos os seus servos fiéis,<br /> o povo de Israel, a quem ele tanto ama.<br /> Aleluia!",
